entries[177869] = { ["name"] = "Leitendes Licht des harmonischen Beobachters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nBenötigt Ruhmstufe 37\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[177870] = { ["name"] = "Thenios' Leuchtfeuer der Voraussicht", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+31 Intelligenz\n+15 Ausdauer\n+ 6 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 14.\nVerkaufspreis:" }
entries[177871] = { ["name"] = "Zweifelsgetrübte Gleve", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nVerdient den Erfolg \"Es ist, wie Ihr es tragt\", um diese Waffenvorlage zu kaufen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[177872] = { ["name"] = "Leitende Gleve der Archon", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n37 - 70 Schaden Geschwindigkeit 3.60\n(14.9 Schaden pro Sekunde)\n+20 Beweglichkeit\n+30 Ausdauer\n+ 28 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 12.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[177873] = { ["name"] = "Dunkelmond-Karte der Unbeugsamkeit", ["text"] = "\"Irgendeine Dunkelmond-Karte der Unbeugsamkeit. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[177874] = { ["name"] = "Dunkelmond-Karte der Gier", ["text"] = "\"Eine zufällige Dunkelmond-Karte der Gier. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[177875] = { ["name"] = "Dunkelmond-Karte der Fäulnis", ["text"] = "\"Eine zufällige Dunkelmond-Karte der Fäulnis. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[177876] = { ["name"] = "Dunkelmond-Karte der Rast", ["text"] = "\"Eine zufällige Dunkelmond-Karte der Rast. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[177877] = { ["name"] = "Fläschchen des Teamgeists", ["text"] = "Questgegenstand\nBenutzen: Erhöht die Stärke und das Selbstvertrauen von Verbündeten, die mit diesem Trank bespritzt werden. (5 Sek. Abklingzeit)\n\"Eines der geistreicheren Fläschchen.\"" }
entries[177878] = { ["name"] = "Animazapfen", ["text"] = "Questgegenstand\n\"Eine dunkle blaue Energie pulsiert leicht in diesem Samen.\"" }
entries[177879] = { ["name"] = "Maldraxxusknochenmark", ["text"] = "Questgegenstand\nEinzigartig (4)\n\"Dieses Knochenmark wurde innerhalb von Maldraxxus abgebaut. Am besten, man denkt nicht darüber nach.\"" }
entries[177880] = { ["name"] = "Urzeitlicher Schlamm", ["text"] = "Questgegenstand\nEinzigartig (20)\nBenutzen: Schleudert urzeitlichen Schlamm auf eine Position in der Nähe." }
entries[177881] = { ["name"] = "Nadjias Sündenstein", ["text"] = "Questgegenstand\n\"Die hier enthaltenen Aufzeichnungen beschreiben die abscheulichen Taten der Vicomtesse Eak'le von Asquiron, Vorsteherin des Ordens der Klingen.\"" }
entries[177894] = { ["name"] = "Tonkrug", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Sammelt die Flamme vorsichtig in einem Behältnis, um sie zurück zu Knochenschmiedin Heirmir zu bringen. (3 Sek. Abklingzeit)\n\"Ein Tonkrug zur Aufbewahrung und zum Transport von heißen Kohlen.\"" }
entries[177895] = { ["name"] = "Warmer Tonkrug", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Tonkrug zur Aufbewahrung und zum Transport von heißen Kohlen. Er ist mit Lichfeuer gefüllt und verbreitet eine unangenehme Hitze.\"" }
entries[177904] = { ["name"] = "Totenstein", ["text"] = "Questgegenstand\nBenutzen: Reist zur Andren Seite.\n\"Ähnelt in gewisser Weise einem Ruhestein, wirkt aber einen Hauch tödlicher.\"" }
entries[177905] = { ["name"] = "Totenstein", ["text"] = "Benutzen: Verlässt die Andre Seite." }
entries[177946] = { ["name"] = "Gramledergeschirr", ["text"] = "Benutzen: Verhindert 2 Stunden lang, dass der Spielercharakter beim Reiten in den Schattenlanden benommen wird.\n\nDie Dauer ist für Lederverarbeiter vervierfacht.\nVerkaufspreis:" }
entries[177947] = { ["name"] = "Theotars verlorener Sonnenschirm", ["text"] = "Questgegenstand\nEinzigartig" }
entries[177948] = { ["name"] = "Vulcas verlorener Werkzeugsatz", ["text"] = "Questgegenstand\nEinzigartig" }
entries[177949] = { ["name"] = "Tubbins' verlorene Teekanne", ["text"] = "Questgegenstand\nEinzigartig" }
entries[177950] = { ["name"] = "Falks Notiz", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit immer noch feuchten Blutflecken bedeckt.\"\n<Zum Lesen rechtsklicken>" }
entries[177951] = { ["name"] = "Angeleinte Glimmerfliegen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen Schwarm Glimmerfliegen, der erhebend wirkt und Euch über Land und Wasser schweben lässt. (5 Min Abklingzeit)\n\"Fünf der besten Glimmerfliegen der Bastion, die mit Schnüren aus Anima angeleint sind.\"\nVerkaufspreis:" }
entries[177953] = { ["name"] = "Ungezähmter Geist", ["text"] = "Konservatorium der Königin\nQuestgegenstand\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit diesem Geist.\n\"Dieser Geist enthält die Essenz eines ungezähmten Wesens.\"\nVerkaufspreis:" }
entries[177954] = { ["name"] = "Kondensiertes Animapartikel", ["text"] = "Questgegenstand\n\"Ein Bruchteil von dem, was der Extraktor in besseren Zeiten produziert hätte.\"" }
entries[177955] = { ["name"] = "Verdorbene Verunreinigung", ["text"] = "Wird beim Aufheben gebunden\n\"Die Niederlage von N'Zoth hat dieses Exemplar aller Kraft beraubt.\"\nVerkaufspreis:" }
entries[177957] = { ["name"] = "Benötigte Verstärker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine besondere Formel, die die Kampffähigkeiten verbessern soll.\"\nVerkaufspreis:" }
entries[177958] = { ["name"] = "Dämmerwaldbericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Das blutgetränkte Pergament lässt Details vermissen, aber es wird sehr deutlich, dass sofortige Verstärkung erforderlich ist.\"" }
entries[177959] = { ["name"] = "Rotkammbericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Hastig aufgeschriebene Notizen, die eine zunehmende Präsenz der Geißel schildern.\"" }
entries[177960] = { ["name"] = "Elwynnbericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein kurzer Bericht über Begegnungen mit der Geißel.\"" }
entries[177961] = { ["name"] = "Seuchenprobe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine intakte Seuchenphiole. Ihr könnt die Beschriftung darauf nicht entziffern.\"" }
entries[177962] = { ["name"] = "Brust - Ewige Werte", ["text"] = "Benutzen: Eine Brustrüstung dauerhaft verzaubern, sodass Primärwerte um 80 erhöht werden. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[177963] = { ["name"] = "Geläuterte Rüstungsfragmente", ["text"] = "Questgegenstand\nEinzigartig\n\"Anima bringt dieses schwarze Metallfragment zum Schimmern. Teile von Runen sind zu erkennen. Es ist nicht mehr mit der grünen Seuche bedeckt.\"" }
entries[177964] = { ["name"] = "Waffe - Kraftmultiplikator", ["text"] = "+ 15 Verderbnis\nBenutzen: Kontaminiert einen Gegenstand mit einer bösartigen Variante von N'Zoths Verderbnis.\n\nTödlicher Schwung\nEure kritischen Treffer haben eine Chance, Euren kritischen Trefferwert für 30 Sek. um 9 zu erhöhen. Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[177965] = { ["name"] = "Verdorbene Verunreinigung", ["text"] = "Wird beim Aufheben gebunden\n\"Die Niederlage von N'Zoth hat dieses Exemplar aller Kraft beraubt.\"\nVerkaufspreis:" }
