entries[178016] = { ["name"] = "Potenzieller Katalysator", ["text"] = "Questgegenstand\n\"Das könnte sein, wonach die Wächterin gesucht hat. Sieht fast aus wie der, den Sie Euch gegeben hat.\"" }
entries[178017] = { ["name"] = "Drusthaut", ["text"] = "Verkaufspreis:" }
entries[178018] = { ["name"] = "Schlüssel des Brandmals", ["text"] = "Questgegenstand\n\"Die Initialen \"BdB\" sind in den Schlüssel eingraviert, umrandet von einem... Herzen?\"" }
entries[178019] = { ["name"] = "Zusätzliche Schriften des Sieges", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Ein einzelnes Buch der scheinbar endlosen Reihe der Schriften des Sieges.\"" }
entries[178020] = { ["name"] = "Schrift des Sieges: Band 1", ["text"] = "Questgegenstand\n\"Der erste Band der scheinbar endlosen Reihe der Schriften des Sieges.\"" }
entries[178021] = { ["name"] = "Culexholzlangbogen", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n14 - 20 Schaden Geschwindigkeit 3.00\n(5.7 Schaden pro Sekunde)\n+8 Beweglichkeit\n+11 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 8.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[178022] = { ["name"] = "Culexholzmesser", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n5 - 10 Schaden Geschwindigkeit 1.80\n(4.2 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[178023] = { ["name"] = "Gormhüllenklopper", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n9 - 13 Schaden Geschwindigkeit 2.60\n(4.2 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 75 / 75\nVerkaufspreis:" }
entries[178024] = { ["name"] = "Gormhüllenknüttel", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n17 - 23 Schaden Geschwindigkeit 3.60\n(5.6 Schaden pro Sekunde)\n+8 Stärke\n+11 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
